package io.github.wadahiro.keycloak.undertow;

import java.io.*;
import java.util.*;

/** Generated by the runtime Maven plugin; Keycloak dependencies stay outside the test classpath. */
record RuntimeDescriptor(String version, int javaFeature, String mainClass, String classpath) {
    static RuntimeDescriptor select(String requested) throws IOException {
        var descriptors = new TreeMap<String, RuntimeDescriptor>((a,b) -> {
            String[] x=a.split("[.]"), y=b.split("[.]");
            for (int i=0;i<Math.min(x.length,y.length);i++) {
                int order=Integer.compare(Integer.parseInt(x[i]),Integer.parseInt(y[i])); if(order!=0)return order;
            }
            return Integer.compare(x.length,y.length);
        });
        var resources=RuntimeDescriptor.class.getClassLoader().getResources("META-INF/keycloak-test-runtime.properties");
        while(resources.hasMoreElements()) {
            Properties properties=new Properties();
            try(var in=resources.nextElement().openStream()) { properties.load(in); }
            var d=new RuntimeDescriptor(properties.getProperty("version"),Integer.parseInt(properties.getProperty("java")),properties.getProperty("mainClass"),properties.getProperty("classpath"));
            descriptors.put(d.version(),d);
        }
        if(descriptors.isEmpty())throw new IllegalStateException("No Keycloak runtime classpath is prepared. Run the keycloak-test-runtime:prepare Maven goal (or bind it to process-test-classes) and refresh the IDE test classpath.");
        if(requested!=null) {
            var result=descriptors.get(requested);
            if(result==null)throw new IllegalArgumentException("Keycloak "+requested+" is not configured; add the matching runtime artifact under keycloak-test-runtime-maven-plugin dependencies and rerun prepare");
            return result;
        }
        return descriptors.lastEntry().getValue();
    }
}
